# -*- coding: utf-8 -*-
"""Punto de entrada autosuficiente para HydroCalc PRO.
Auto-extrae y actualiza siempre los archivos más recientes en el servidor.
"""
import os
import sys
import base64
import io
import zipfile

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
if BASE_DIR not in sys.path:
    sys.path.insert(0, BASE_DIR)

EMBEDDED_ZIP_DATA = ""

# Extraer y actualizar siempre con la versión más reciente de HydroCalc
try:
    raw_zip = base64.b64decode(EMBEDDED_ZIP_DATA)
    with zipfile.ZipFile(io.BytesIO(raw_zip)) as z:
        z.extractall(BASE_DIR)
    print('[HYDROCALC] Archivos desplegados y actualizados exitosamente.')
except Exception as e:
    print('[HYDROCALC ERROR]', e)

from app import create_app

app = create_app()

if __name__ == '__main__':
    puerto = int(os.environ.get('PORT', 5000))
    app.run(host='0.0.0.0', port=puerto, debug=False)
